import itertools

def gadget(lits):
    # lits: list of three literals as ints (+v or -v)
    # We'll use new variable y (positive integer 100) for each clause
    y = 100
    # clause1: (l1, l2, y)
    # clause2: (l1, l3, -y)
    # clause3: (l2, l3, -y)
    return [[lits[0], lits[1], y], [lits[0], lits[2], -y], [lits[1], lits[2], -y]]

def eval_clause(clause, assign):
    # assign dict var->bool
    vals = []
    for lit in clause:
        var = abs(lit)
        val = assign.get(var, False)
        if lit < 0:
            val = not val
        vals.append(val)
    # NAE satisfied if not all equal
    return not (all(vals) or not any(vals))

def original_satisfied(lits, assign):
    return any(((assign[abs(l)] if l>0 else not assign[abs(l)]) for l in lits)

# test all combos of literals (variables 1,2,3) and assignments
vars = [1,2,3]
for lits in itertools.product([1,-1,2,-2,3,-3], repeat=3):
    # ensure distinct variables
    if len({abs(l) for l in lits})!=3:
        continue
    # test all assignments of vars 1..3 and y=100
    ok=True
    for bits in itertools.product([False,True], repeat=4):
        assign={1:bits[0],2:bits[1],3:bits[2],100:bits[3]}
        orig=original_satisfied(lits, assign)
        # evaluate gadget clauses all must be satisfied
        gag = all(eval_clause(c, assign) for c in gadget(lits))
        if orig!=gag:
            ok=False
            break
    if not ok:
        print('counterexample', lits)
        break
else:
    print('all good')
PY"}

