import itertools, sys

orig_vars = [1,2,3]
new_vars = [4,5]
all_vars = orig_vars + new_vars

def all_literal_options(var):
    return [var, -var]

# generate all possible clauses (list of 3 literals) respecting distinct vars and no var and its neg both.
clauses = []
for vars_combo in itertools.combinations(all_vars,3):
    # for each sign assignment
    for signs in itertools.product([1,-1], repeat=3):
        lits = [v*sign for v,sign in zip(vars_combo, signs)]
        # ensure not both v and -v in same clause (impossible because distinct vars)
        clauses.append(lits)

# function to evaluate NAE clause
def eval_nae(clause, assign):
    vals = []
    for lit in clause:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def original_clause_sat(lits, assign):
    # lits are 3 literals of original variables (with signs)
    for lit in lits:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        if val:
            return True
    return False

# search for gadget with up to 3 clauses using new vars 4,5 possibly.
max_clauses = 3
for k in range(1, max_clauses+1):
    for combo in itertools.combinations(clauses, k):
        # Ensure each clause uses at most new vars? no restriction.
        # Test condition for all sign combos of original literals.
        ok = True
        for sign_combo in itertools.product([1,-1], repeat=3):
            orig_lits = [v*sign for v,sign in zip(orig_vars, sign_combo)]
            # test all assignments to orig vars (1..3) and new vars (4,5)
            for bits in itertools.product([False,True], repeat=5):
                assign = {i:bits[i-1] for i in range(1,6)}
                orig_sat = original_clause_sat(orig_lits, assign)
                # gadget satisfied if all clauses NAE satisfied
                gag_sat = all(eval_nae(c, assign) for c in combo)
                if orig_sat != gag_sat:
                    ok=False
                    break
            if not ok:
                break
        if ok:
            print('Found gadget with',k,'clauses')
            for c in combo:
                print(c)
            sys.exit()
print('none found')
