import itertools, sys

def reduction(orig_clauses, m):
    # m original vars count
    # introduce a= m+1, b=m+2
    a = m+1
    b = m+2
    new_clauses = []
    # add inequality clause (a,b,b)
    new_clauses.append([a,b,b])
    for clause in orig_clauses:
        l1,l2,l3 = clause
        new_clauses.append([l1,l2,a])
        new_clauses.append([l3,b,a])
    return (m+2, new_clauses)

def eval_nae_clause(clause, assign):
    vals = []
    for lit in clause:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def eval_three_sat(clause, assign):
    for lit in clause:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        if val:
            return True
    return False

def check(m, orig_clauses):
    # test all assignments to original vars plus a,b
    a=m+1; b=m+2
    for bits in itertools.product([False,True], repeat=m+2):
        assign={i+1:bits[i] for i in range(m+2)}
        orig_sat = all(eval_three_sat(c, assign) for c in orig_clauses)
        # reduction instance
        new_m,new_clauses = reduction(orig_clauses,m)
        red_sat = all(eval_nae_clause(c, assign) for c in new_clauses)
        if orig_sat != red_sat:
            print('mismatch', m, orig_clauses, assign, orig_sat, red_sat)
            return False
    return True

# test random small instances
for m in range(0,4):
