import itertools, sys

orig_vars = [1,2,3]
new_vars = [4,5]
all_vars = orig_vars + new_vars

# generate all possible literals for each var (positive or negative)

def all_literals(vars_list):
    lits = []
    for v in vars_list:
        lits.append(v)
        lits.append(-v)
    return lits

literals = all_literals(all_vars)

# generate all possible NAE clauses (3 distinct vars, distinct absolute values)
clauses = []
for combo in itertools.combinations(literals,3):
    # check distinct vars
    if len({abs(l) for l in combo})!=3:
        continue
    # also ensure not both v and -v present (already distinct var ensures that)
    clauses.append(list(combo))

# evaluate NAE clause
def eval_nae(clause, assign):
    vals = []
    for lit in clause:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def eval_orig(clause, assign):
    # clause is list of 3 literals (orig only vars 1..3)
    for lit in clause:
        v = abs(lit)
        val = assign.get(v, False)
        if lit < 0:
            val = not val
        if val:
            return True
    return False

# test all sign combos for original clause literals
orig_sign_combos = []
for signs in itertools.product([1,-1], repeat=3):
    lits = [v*sign for v,sign in zip(orig_vars, signs)]
    orig_sign_combos.append(lits)

# search for gadget using up to 3 clauses
max_clauses = 3
for k in range(1, max_clauses+1):
    for combo in itertools.combinations(clauses, k):
        # ensure each clause uses only literals from set where new vars may appear any sign
        ok = True
        for orig_lits in orig_sign_combos:
            # test all assignments to vars 1..3 and new vars 4,5
            for bits in itertools.product([False,True], repeat=5):
                assign = {i+1:bits[i] for i in range(5)}
                orig_sat = eval_orig(orig_lits, assign)
                # need existence of assignment to new vars? Wait new vars are part of assign already. The reduction should allow choosing new vars arbitrarily per clause. So we just check if there exists assignment to new vars (4,5) making all gadget clauses satisfied given fixed original assignment.
                # So we need to check: exists values for new vars (4,5) such that all NAE clauses satisfied.
                # We'll brute over all possibilities for new vars values.
                exists = False
                for new_bits in itertools.product([False,True], repeat=2):
                    assign2 = assign.copy()
                    assign2[4]=new_bits[0]
                    assign2[5]=new_bits[1]
                    if all(eval_nae(c, assign2) for c in combo):
                        exists = True
                        break
                if orig_sat != exists:
                    ok=False
                    break
            if not ok:
                break
        if ok:
            print('Found gadget with',k,'clauses')
            for c in combo:
                print(c)
            sys.exit()
print('No gadget found')
