import itertools, sys
orig_vars = [1,2,3]
new_vars = [4,5]
all_vars = orig_vars + new_vars
# generate all possible literals for each var
lits = []
for v in all_vars:
    lits.append(v)
    lits.append(-v)
# generate all possible NAE clauses (3 distinct vars)
clauses = []
for combo in itertools.combinations(lits,3):
    if len({abs(l) for l in combo})==3:
        clauses.append(list(combo))

def eval_nae(clause, assign):
    vals = []
    for lit in clause:
        v = abs(lit)
        val = assign[v]
        if lit < 0:
            val = not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def orig_sat(lits, assign):
    for lit in lits:
        v = abs(lit)
        val = assign[v]
        if lit < 0:
            val = not val
        if val:
            return True
    return False

# all sign combos for original clause
orig_signs = []
for signs in itertools.product([1,-1], repeat=3):
    orig_signs.append([v*sign for v,sign in zip(orig_vars, signs)])

max_clauses = 3
for k in range(1, max_clauses+1):
    for combo in itertools.combinations(clauses, k):
        ok=True
        for orig in orig_signs:
            # for each assignment to original vars, need existence of new vars assignment satisfying all clauses
            for bits in itertools.product([False,True], repeat=3): # original vars assignments
                assign = {1:bits[0],2:bits[1],3:bits[2]}
                orig_ok = orig_sat(orig, assign)
                # check existence of new vars values (4,5) such that all clauses satisfied
                exists=False
                for newbits in itertools.product([False,True], repeat=2):
                    assign2 = assign.copy()
                    assign2[4]=newbits[0]
                    assign2[5]=newbits[1]
                    if all(eval_nae(c, assign2) for c in combo):
                        exists=True
                        break
                if orig_ok != exists:
                    ok=False
                    break
            if not ok:
                break
        if ok:
            print('Found gadget with',k,'clauses')
            for c in combo:
                print(c)
            sys.exit()
print('No gadget found')
