import itertools, sys
orig_vars = ['l1','l2','l3']
# map to indices 1,2,3 for evaluation
var_index = {'l1':1,'l2':2,'l3':3,'y':4}

def lit_to_int(lit):
    # lit is tuple (var, sign) sign True positive
    var, sign = lit
    v = var_index[var]
    return v if sign else -v

def eval_nae(clause, assign):
    vals=[]
    for lit in clause:
        v=abs(lit)
        val=assign[v]
        if lit<0:
            val=not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def eval_or(lits, assign):
    for lit in lits:
        v=abs(lit)
        val=assign[v]
        if lit<0:
            val=not val
        if val:
            return True
    return False

# generate all possible NAE clauses using literals from l1,l2,l3,y (positive/negative) with distinct vars
vars = ['l1','l2','l3','y']
literals=[]
for v in vars:
    literals.append((v,True))
    literals.append((v,False))
# convert to int later

def clause_to_ints(combo):
    return [lit_to_int(l) for l in combo]

nae_clauses=[]
for combo in itertools.combinations(literals,3):
    if len({v for v,_ in combo})==3:
        nae_clauses.append(clause_to_ints(combo))

# search for up to 2 clauses gadget
orig_signs=[]
for signs in itertools.product([True,False], repeat=3):
    orig_lits=[lit_to_int((v,sg)) for v,sg in zip(['l1','l2','l3'], signs)]
    orig_signs.append(orig_lits)

for k in range(1,3):
    for gadget in itertools.combinations(nae_clauses, k):
        ok=True
        for orig in orig_signs:
            for bits in itertools.product([False,True], repeat=3):
                assign_orig={1:bits[0],2:bits[1],3:bits[2]}
                or_val=eval_or(orig, assign_orig)
                # need existence of y assignment (var 4) such that all gadget clauses satisfied
                exists=False
                for y_val in [False,True]:
                    assign=assign_orig.copy(); assign[4]=y_val
                    if all(eval_nae(c, assign) for c in gadget):
                        exists=True
                        break
                if or_val!=exists:
                    ok=False
                    break
            if not ok:
                break
        if ok:
            print('Found gadget with',k,'clauses')
            for c in gadget:
                print(c)
            sys.exit()
print('No gadget found')
